	private void rememberFieldDefaultState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean makeFinal) {
		this.fieldDefaultType = typeNode;
		this.fieldDefaultError = errorNode;
		this.fieldDefaultAccess = level;
		this.fieldDefaultMakeFinal = makeFinal;
	}

	private boolean fieldDefaultTypeIsUsable() {

		return fieldDefaultType != null && fieldDefaultError != null;
	}

	private void applyRememberedFieldDefaultsToEachField() {

		if (!fieldDefaultTypeIsUsable()) return;
		for (JavacNode field : fieldDefaultType.down()) {
			if (field.getKind() != Kind.FIELD) continue;
			JCVariableDecl fieldDecl = (JCVariableDecl) field.get();
			if (fieldDecl.name.toString().startsWith("$")) continue;
			setFieldDefaultsForField(field, fieldDefaultAccess, fieldDefaultMakeFinal);
		}
	}

	public boolean applyFieldDefaultsUsingRememberedState(boolean checkForTypeLevelFieldDefaults) {

		if (!fieldDefaultTypeIsUsable()) return false;
		if (checkForTypeLevelFieldDefaults && hasAnnotation(FieldDefaults.class, fieldDefaultType)) return true;
		if (!isClassOrEnum(fieldDefaultType)) {
			fieldDefaultError.addError("@FieldDefaults is only supported on a class or an enum.");
			return false;
		}
		applyRememberedFieldDefaultsToEachField();
		return true;
	}

	private void rememberGetterState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		this.getterTypeNode = typeNode;
		this.getterErrorNode = errorNode;
		this.getterLevel = level;
		this.getterCheckForTypeLevel = checkForTypeLevelGetter;
		this.getterOnMethod = onMethod;
		this.getterLazy = false;
	}

	private boolean getterStateIsReady() {

		return getterTypeNode != null && getterErrorNode != null;
	}

	private void generateRememberedGetters() {

		if (!getterStateIsReady()) return;
		if (getterCheckForTypeLevel && hasAnnotation(Getter.class, getterTypeNode)) return;
		if (!isClassOrEnum(getterTypeNode)) {
			getterErrorNode.addError(GETTER_NODE_NOT_SUPPORTED_ERR);
			return;
		}
		for (JavacNode field : getterTypeNode.down()) {
			if (fieldQualifiesForGetterGeneration(field)) {
				generateGetterForField(field, getterErrorNode.get(), getterLevel, getterLazy, getterOnMethod);
			}
		}
	}

	public void applyGetterGeneration(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelGetter, List<JCAnnotation> onMethod) {
		this.getterTypeNode = typeNode;
		this.getterErrorNode = errorNode;
		this.getterLevel = level;
		this.getterOnMethod = onMethod;
		this.getterCheckForTypeLevel = checkForTypeLevelGetter;


		rememberGetterState(typeNode, errorNode, level, checkForTypeLevelGetter, onMethod);
		if (getterStateIsReady()) generateRememberedGetters();
	}

	private void rememberSetterState(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterTypeNode = typeNode;
		this.setterErrorNode = errorNode;
		this.setterLevel = level;
		this.setterCheckForTypeLevel = checkForTypeLevelSetter;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
	}

	private boolean setterStateIsReady() {

		return setterTypeNode != null && setterErrorNode != null;
	}

	private void generateRememberedSetters() {

		if (!setterStateIsReady()) return;
		generateSetterForType(setterTypeNode, setterErrorNode, setterLevel, setterCheckForTypeLevel, setterOnMethod, setterOnParam);
	}

	public void applySetterGeneration(JavacNode typeNode, JavacNode errorNode, AccessLevel level, boolean checkForTypeLevelSetter, List<JCAnnotation> onMethod, List<JCAnnotation> onParam) {
		this.setterTypeNode = typeNode;
		this.setterErrorNode = errorNode;
		this.setterLevel = level;
		this.setterOnMethod = onMethod;
		this.setterOnParam = onParam;
		this.setterCheckForTypeLevel = checkForTypeLevelSetter;


		rememberSetterState(typeNode, errorNode, level, checkForTypeLevelSetter, onMethod, onParam);
		if (setterStateIsReady()) generateRememberedSetters();
	}

